package com.huy.enterprise.product; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/products") @RequiredArgsConstructor public class ProductController {private final ProductService service;@GetMapping List<ProductResponse> all(){return service.all();}@GetMapping("/{id}") ProductResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) ProductResponse create(@Valid @RequestBody ProductRequest r){return service.create(r);}@PutMapping("/{id}") ProductResponse update(@PathVariable UUID id,@Valid @RequestBody ProductRequest r){return service.update(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){service.delete(id);}}
